(function (){window.validateStep1=function (){var name=document.getElementById('reg_name').value.trim();var email=document.getElementById('reg_email').value.trim();var phone=document.getElementById('reg_phone').value.trim();var nationality=document.getElementById('reg_nationality').value;if (!name){alert('يرجى إدخال اسم الطالب الكامل.');return false;}if (!email){alert('يرجى إدخال البريد الإلكتروني.');return false;}var emailReg=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;if (!emailReg.test(email)){alert('يرجى إدخال بريد إلكتروني صحيح.');return false;}if (!phone){alert('يرجى إدخال رقم الهاتف.');return false;}if (!nationality){alert('يرجى اختيار الجنسية.');return false;}if (['دولة اخرى غير موجودة','دولة أخرى غير موجودة','دولة أخرى','أخرى'].indexOf(nationality)!==-1){var customNat=document.getElementById('reg_custom_nationality');if (customNat&&!customNat.value.trim()){alert('يرجى كتابة اسم الدولة/الجنسية الأخرى.');return false;}}return true;};})();